REPLY
    ;;
  listpays)
    cat <<'REPLY'
{"pays": [{"payment_hash": "b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2", "amount_msat": 10000, "amount_sent_msat": 10250, "status": "complete", "completed_at": 1736463000, "destination": "022222222222222222222222222222222222222222222222222222222222222222", "payment_preimage": "private"}, {"amount_msat": 4000, "amount_sent_msat": 4000, "status": "pending", "created_at": 1736463000}, {"amount_msat": 3000, "amount_sent_msat": 3100, "status": "complete", "created_at": 1736460000, "rebalance": true}]}
REPLY
    ;;
  bkpr-listincome)
    cat <<'REPLY'
{"income_events": [{"account": "chan-1", "tag": "invoice", "credit_msat": 25000, "debit_msat": 0, "timestamp": 1736460000, "payment_id": "a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1", "description": "Coffee income", "currency": "bcrt"}, {"account": "wallet", "tag": "invoice", "credit_msat": 7000, "txid": "f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6", "timestamp": 1736460000}, {"account": "chan-1", "tag": "routed", "credit_msat": 1500, "timestamp": 1736463600}]}
REPLY
    ;;
  bkpr-listbalances)
    cat <<'REPLY'
{"accounts": [{"account": "wallet", "balances": [{"balance_msat": 5000, "coin_type": "bcrt"}]}, {"account": "chan-1", "peer_id": "peer-a", "balances": [{"balance_msat": "1000000msat"}], "account_closed": false}]}
REPLY
    ;;
  bkpr-listaccountevents)
    cat <<'REPLY'
{"events": [{"account": "chan-1", "tag": "channel_open", "outpoint": "c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3:0", "credit_msat": 1000000, "timestamp": 1736400000}, {"account": "chan-3", "tag": "channel_close", "txid": "d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4", "debit_msat": 400000, "timestamp": 1736500000}, {"account": "chan-3", "tag": "channel_open", "txid": "a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7", "credit_msat": 400000}]}
REPLY
    ;;
  *)
    echo DISCARDED_CLN_STDERR_SECRET >&2
    exit 7
    ;;
esac

